/**
 * corpus-score.mjs — the onset detector's real miss / false-alarm rate.
 *
 * Feeds every LibriSpeech dev-clean file we have (209) through the SHIPPING
 * detector (core/onset.js, imported — not copied, not edited; it is browser-free
 * by design, so node runs the identical arithmetic the AudioWorklet does) and
 * scores its events against media/labels-full.json, whose labels come from
 * criteria deliberately independent of the detector (see labels-full.mjs).
 *
 * Noise sweep: each file is also mixed with calibrated pink noise (generated by
 * ffmpeg's anoisesrc) at several absolute floor levels, to find the floor above
 * which breath detection collapses — the number the noise-ceiling UI needs.
 *
 * Scoring rules (all stated, no hidden choices):
 *   "Detectable" (scored) means the event could physically trip a 5 dB-SNR gate:
 *   enough time since the previous speech segment, AND at least HEADROOM_MIN_DB
 *   of rise from the actual audio level in the 500 ms beforehand to the event's
 *   own peak. The headroom test matters: most automatic breath labels turn out
 *   to be dips inside loud regions (the 500 ms before them is LOUDER than the
 *   "breath"), which no threshold detector can fire on — scoring those as misses
 *   would measure the labeler, not the detector.
 *
 *   SPEECH  a detectable segment ≥700 ms is a MISS unless an onset fires within
 *           [start−700, start+500] ms. Timing error = nearest matched onset −
 *           label start (negative = early, e.g. caught the breath). A segment
 *           with no matched onset but an already-open turn is counted MERGED —
 *           the detector reported the audio, it just never re-segmented.
 *   BREATH  a detectable breath is a MISS unless an onset fires within
 *           [start−400, end+200] ms (early side is wide on purpose: the detector
 *           is more sensitive than the labeler's -52 dBFS band edge and fires on
 *           the ramp — an early onset on the ramp is a detection, not an FA).
 *           A detected breath is CLASSIFIED if the detector's own label for that
 *           onset is 'breath', and VOICED if a `voiced` event (the head-start
 *           measurement) followed. Same MERGED rule as speech.
 *   FALSE   an onset matching no breath and no speech onset, landing outside the
 *   ALARM   union of all speech activity (≥100 ms, dilated ±300 ms), all breath
 *           windows (dilated −400/+250 ms), and the first 400 ms (calibration).
 *
 * Writes media/corpus-score-results.json and prints the tables. New file; edits nothing.
 */

import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
const { OnsetDetector, SAMPLE_RATE } = await import(process.env.ONSET_PATH ?? '../tape-app/public/core/onset.js');

const DET_OPTS = {};
if (process.env.TURN_DROP_DB) DET_OPTS.turnDropDb = +process.env.TURN_DROP_DB;
if (process.env.RECLASSIFY_MS) DET_OPTS.reclassifyMs = +process.env.RECLASSIFY_MS;
if (process.env.AWAIT_HANG_MS) DET_OPTS.awaitVoiceHangMs = +process.env.AWAIT_HANG_MS;
console.log('DET_OPTS', JSON.stringify(DET_OPTS));

const HERE = dirname(fileURLToPath(import.meta.url));
const MEDIA = join(HERE, 'media');
const SR = SAMPLE_RATE; // 48000 — the detector's own constant, not a retype

const LEVELS = [null, -55, -50, -45, -40, -35, -30]; // null = clean, no added noise
const CAL_GUARD_MS = 400;   // detector calibrates on the first 150 ms of real audio
const SPEECH_DET_WIN = [-700, 500];
const BREATH_DET_WIN = [-250, 200]; // relative to [start, end]; -250 covers the measured
//                                    earliest true ramp-fire (215 ms early at clean)
const SPEECH_TIMING_WIN = 250; // |error| beyond this is reported but flagged breath-caught
const HEADROOM_MIN_DB = 6; // event peak minus preceding 500 ms level — see header

const labels = JSON.parse(readFileSync(join(MEDIA, 'labels-full.json'), 'utf8'));

function decode(flac) {
  const buf = execFileSync(
    'ffmpeg',
    ['-v', 'error', '-i', flac, '-ac', '1', '-ar', String(SR), '-f', 'f32le', '-'],
    { maxBuffer: 1 << 28 },
  );
  return new Float32Array(buf.buffer, buf.byteOffset, buf.length / 4);
}

// Calibrated background noise, generated by ffmpeg as the task specifies.
// One long pink-noise buffer; each (file, level) mixes from a deterministic offset.
console.log('generating calibrated pink noise via ffmpeg…');
const noiseBuf = (() => {
  const buf = execFileSync(
    'ffmpeg',
    ['-v', 'error', '-f', 'lavfi', '-i',
      'anoisesrc=color=pink:amplitude=1:sample_rate=48000:duration=70:seed=42',
      '-ac', '1', '-f', 'f32le', '-'],
    { maxBuffer: 1 << 28 },
  );
  return new Float32Array(buf.buffer, buf.byteOffset, buf.length / 4);
})();
let noiseRms = 0;
for (let i = 0; i < noiseBuf.length; i++) noiseRms += noiseBuf[i] * noiseBuf[i];
noiseRms = Math.sqrt(noiseRms / noiseBuf.length);
console.log(`  noise RMS ${(20 * Math.log10(noiseRms)).toFixed(1)} dBFS at amplitude=1 — scaling from this`);

function runDetector(x) {
  const det = new OnsetDetector(DET_OPTS);
  const events = det.push(x);
  // Assemble per-onset records.
  const onsets = [];
  const byAt = new Map();
  for (const e of events) {
    if (e.type === 'onset') {
      const rec = {
        atMs: (e.at / SR) * 1000, snrDb: +e.snrDb.toFixed(2), floorDb: +e.floorDb.toFixed(2),
        kind: null, leadMs: null,
      };
      onsets.push(rec);
      byAt.set(e.at, rec);
    } else if (e.type === 'classified') {
      const rec = byAt.get(e.onsetAt);
      if (rec) rec.kind = e.kind;
    } else if (e.type === 'voiced') {
      const rec = byAt.get(e.onsetAt);
      if (rec) rec.leadMs = +e.leadMs.toFixed(1);
    }
  }
  const ends = events
    .filter((e) => e.type === 'end')
    .map((e) => ({ atMs: (e.at / SR) * 1000, forced: !!e.forced, reason: e.reason }));
  return {
    onsets,
    ends,
    forcedEnds: ends.filter((e) => e.forced).map((e) => e.reason),
  };
}

const pct = (xs, p) => {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b);
  return +s[Math.min(s.length - 1, Math.floor((p / 100) * s.length))].toFixed(1);
};

// Measured floor of the mixed signal: median 10 ms-frame dBFS outside speech+breath.
function measuredFloorDb(x, file) {
  const mask = [];
  for (const s of file.speech) mask.push([s.startMs - 300, s.endMs + 300]);
  for (const b of file.breaths) mask.push([b.startMs - 150, b.endMs + 250]);
  const WIN = 480;
  const vals = [];
  for (let i = 0; i + WIN <= x.length; i += WIN) {
    const tms = (i / SR) * 1000;
    if (mask.some(([a, b]) => tms >= a && tms <= b)) continue;
    let s = 0;
    for (let j = 0; j < WIN; j++) s += x[i + j] * x[i + j];
    vals.push(20 * Math.log10(Math.sqrt(s / WIN) + 1e-12));
  }
  vals.sort((a, b) => a - b);
  return vals.length ? +vals[Math.floor(vals.length / 2)].toFixed(1) : null;
}

const results = LEVELS.map((level) => ({
  level: level === null ? 'clean' : `${level} dBFS`,
  targetDbfs: level,
  speech: { scored: 0, detected: 0, missed: 0, merged: 0, errorsMs: [], breathCaught: 0 },
  breath: { scored: 0, detected: 0, missed: 0, merged: 0, classified: 0, voiced: 0, errorsMs: [], missedPeaks: [], detectedPeaks: [], trials: [], kinds: {} },
  fa: { count: 0, byKind: {}, snrDb: [], quietMs: 0 },
  forcedEnds: { flat: 0, stuck: 0, 'never-quiet': 0 },
  minutes: 0,
  floors: [],
}));

for (let fi = 0; fi < labels.files.length; fi++) {
  const f = labels.files[fi];
  const clean = decode(f.path);

  // Scored sets are level-independent — build once per file.
  const mask = [[0, CAL_GUARD_MS]];
  for (const s of f.speech) mask.push([s.startMs - 300, s.endMs + 300]);
  for (const b of f.breaths) mask.push([b.startMs + BREATH_DET_WIN[0], b.endMs + 250]);
  const inMask = (t) => mask.some(([a, b]) => t >= a && t <= b);
  // Union of mask intervals → quiet time, the denominator a false-alarm rate
  // belongs to (FAs can only fire out of mask). These files are speech-dense:
  // per-total-minute normalisation would understate the FA rate ~5×.
  const sorted = [...mask].sort((a, b) => a[0] - b[0]);
  let maskedMs = 0, curS = null, curE = null;
  for (const [a, b] of sorted) {
    if (curS === null) { curS = a; curE = b; continue; }
    if (a <= curE) { curE = Math.max(curE, b); continue; }
    maskedMs += curE - curS; curS = a; curE = b;
  }
  if (curS !== null) maskedMs += curE - curS;
  const quietMs = Math.max(0, f.durMs - maskedMs);
  // Physics screen: the event must rise at least HEADROOM_MIN_DB above the level
  // of the 500 ms before it. Below that, no detector with a 5 dB SNR gate could
  // fire — the label is a dip in a loud region, not a discrete audible onset.
  const headroom = (ev) =>
    ev.floorBeforeDbfs != null && ev.peakDbfs - ev.floorBeforeDbfs >= HEADROOM_MIN_DB;
  const scoredSpeech = f.speech.filter((s, idx) => {
    if (!s.scored || s.startMs < CAL_GUARD_MS) return false;
    const prevEnd = idx > 0 ? f.speech[idx - 1].endMs : 0;
    return s.startMs - prevEnd >= labels.criteria.QUIET_BEFORE_MS && headroom(s);
  });
  const scoredBreaths = f.breaths.filter(
    (b) => b.quietBeforeMs >= 400 && b.startMs >= CAL_GUARD_MS && headroom(b),
  );

  for (let li = 0; li < LEVELS.length; li++) {
    const level = LEVELS[li];
    const gain = level === null ? 0 : 10 ** (level / 20) / noiseRms;
    const R = results[li];
    let x = clean;
    if (gain > 0) {
      x = new Float32Array(clean.length);
      const off = (fi * 7919 + li * 104729) % Math.max(1, noiseBuf.length - clean.length - 1);
      for (let i = 0; i < clean.length; i++) x[i] = clean[i] + noiseBuf[off + i] * gain;
    }
    R.minutes += f.durMs / 60000;
    R.fa.quietMs += quietMs;
    if (fi % 25 === 0) R.floors.push(measuredFloorDb(x, f));

    const { onsets, ends, forcedEnds } = runDetector(x);
    for (const r of forcedEnds) R.forcedEnds[r] = (R.forcedEnds[r] ?? 0) + 1;
    // Was a turn already open at time t? (End of file counts as an implicit end.)
    const turnOpenAt = (t) => {
      for (const o of onsets) {
        if (o.atMs > t) break;
        const closed = ends.some((e) => e.atMs > o.atMs && e.atMs <= t);
        if (!closed) return true;
      }
      return false;
    };

    for (const s of scoredSpeech) {
      R.speech.scored++;
      const cand = onsets.filter(
        (o) => o.atMs >= s.startMs + SPEECH_DET_WIN[0] && o.atMs <= s.startMs + SPEECH_DET_WIN[1],
      );
      if (!cand.length) {
        if (turnOpenAt(s.startMs)) R.speech.merged++;
        else R.speech.missed++;
        continue;
      }
      R.speech.detected++;
      const nearest = cand.reduce((a, b) => (Math.abs(b.atMs - s.startMs) < Math.abs(a.atMs - s.startMs) ? b : a));
      const err = nearest.atMs - s.startMs;
      R.speech.errorsMs.push(+err.toFixed(1));
      if (err < -SPEECH_TIMING_WIN) R.speech.breathCaught++;
    }

    // Scored breaths.
    for (const b of scoredBreaths) {
      R.breath.scored++;
      const cand = onsets.filter(
        (o) => o.atMs >= b.startMs + BREATH_DET_WIN[0] && o.atMs <= b.endMs + BREATH_DET_WIN[1],
      );
      if (!cand.length) {
        const merged = turnOpenAt(b.startMs);
        if (merged) R.breath.merged++;
        else R.breath.missed++;
        R.breath.missedPeaks.push(b.peakDbfs);
        R.breath.trials.push({ peakDbfs: b.peakDbfs, outcome: merged ? 'merged' : 'missed' });
        continue;
      }
      R.breath.detected++;
      R.breath.detectedPeaks.push(b.peakDbfs);
      R.breath.trials.push({ peakDbfs: b.peakDbfs, outcome: 'detected' });
      const nearest = cand.reduce((a, b2) => (Math.abs(b2.atMs - b.startMs) < Math.abs(a.atMs - b.startMs) ? b2 : a));
      R.breath.errorsMs.push(+(nearest.atMs - b.startMs).toFixed(1));
      R.breath.kinds[nearest.kind ?? 'unclassified'] = (R.breath.kinds[nearest.kind ?? 'unclassified'] ?? 0) + 1;
      if (nearest.kind === 'breath') R.breath.classified++;
      if (nearest.leadMs != null) R.breath.voiced++;
    }

    // False alarms.
    for (const o of onsets) {
      if (o.atMs < CAL_GUARD_MS) continue;
      const matchedBreath = scoredBreaths.some(
        (b) => o.atMs >= b.startMs + BREATH_DET_WIN[0] && o.atMs <= b.endMs + BREATH_DET_WIN[1],
      );
      const matchedSpeech = scoredSpeech.some(
        (s) => o.atMs >= s.startMs + SPEECH_DET_WIN[0] && o.atMs <= s.startMs + SPEECH_DET_WIN[1],
      );
      if (matchedBreath || matchedSpeech) continue;
      if (inMask(o.atMs)) continue; // real sound we chose not to score, not a false alarm
      R.fa.count++;
      R.fa.byKind[o.kind ?? 'unclassified'] = (R.fa.byKind[o.kind ?? 'unclassified'] ?? 0) + 1;
      R.fa.snrDb.push(o.snrDb);
    }
  }
  if (fi % 25 === 0) process.stdout.write(`\r  files ${fi}/${labels.files.length}`);
}
process.stdout.write(`\r  all ${labels.files.length} files × ${LEVELS.length} levels done\n`);

// ── Report ───────────────────────────────────────────────────────────────────
const summary = results.map((R) => ({
  level: R.level,
  measuredFloorDbfs: pct(R.floors.filter((v) => v != null), 50),
  speech: {
    scored: R.speech.scored,
    detected: R.speech.detected,
    missed: R.speech.missed,
    merged: R.speech.merged,
    missRate: +(R.speech.missed / Math.max(1, R.speech.scored)).toFixed(4),
    mergedRate: +(R.speech.merged / Math.max(1, R.speech.scored)).toFixed(4),
    timingP50: pct(R.speech.errorsMs.map(Math.abs), 50),
    timingP95: pct(R.speech.errorsMs.map(Math.abs), 95),
    timingMedianSigned: pct(R.speech.errorsMs, 50),
    breathCaught: R.speech.breathCaught,
  },
  breath: {
    scored: R.breath.scored,
    detected: R.breath.detected,
    missed: R.breath.missed,
    merged: R.breath.merged,
    missRate: +(R.breath.missed / Math.max(1, R.breath.scored)).toFixed(4),
    mergedRate: +(R.breath.merged / Math.max(1, R.breath.scored)).toFixed(4),
    classifiedBreath: R.breath.classified,
    voicedMeasured: R.breath.voiced,
    matchedKinds: R.breath.kinds,
    timingP50: pct(R.breath.errorsMs.map(Math.abs), 50),
    timingP95: pct(R.breath.errorsMs.map(Math.abs), 95),
    timingMedianSigned: pct(R.breath.errorsMs, 50),
  },
  falseAlarms: {
    count: R.fa.count,
    perMinute: +(R.fa.count / Math.max(1e-9, R.minutes)).toFixed(3),
    perQuietMinute: +(R.fa.count / Math.max(1e-9, R.fa.quietMs / 60000)).toFixed(2),
    quietMinutes: +(R.fa.quietMs / 60000).toFixed(1),
    byKind: R.fa.byKind,
    snrMedian: pct(R.fa.snrDb, 50),
  },
  forcedEnds: R.forcedEnds,
  minutes: +R.minutes.toFixed(1),
}));

console.log('\n════ per-level results ════');
for (const s of summary) {
  console.log(`\n── ${s.level}  (measured floor ${s.measuredFloorDbfs} dBFS, ${s.minutes} min) ──`);
  console.log(
    `  speech onsets : ${s.speech.scored} scored, ${s.speech.detected} detected, ${s.speech.missed} missed ` +
      `(${(100 * s.speech.missRate).toFixed(1)}%), ${s.speech.merged} merged into open turn ` +
      `(${(100 * s.speech.mergedRate).toFixed(1)}%), ` +
      `timing |err| p50 ${s.speech.timingP50} ms p95 ${s.speech.timingP95} ms, ` +
      `median signed ${s.speech.timingMedianSigned} ms, breath-caught ${s.speech.breathCaught}`,
  );
  console.log(
    `  breath onsets : ${s.breath.scored} scored, ${s.breath.detected} detected, ${s.breath.missed} missed ` +
      `(${(100 * s.breath.missRate).toFixed(1)}%), ${s.breath.merged} merged ` +
      `(${(100 * s.breath.mergedRate).toFixed(1)}%), ` +
      `classified breath ${s.breath.classifiedBreath}/${s.breath.detected}, ` +
      `voiced measured ${s.breath.voicedMeasured}/${s.breath.detected}, ` +
      `timing |err| p50 ${s.breath.timingP50} ms p95 ${s.breath.timingP95} ms, ` +
      `median signed ${s.breath.timingMedianSigned} ms`,
  );
  console.log(
    `  false alarms  : ${s.falseAlarms.count} (${s.falseAlarms.perMinute}/min, ` +
      `${s.falseAlarms.perQuietMinute}/quiet-min over ${s.falseAlarms.quietMinutes} quiet min), ` +
      `kinds ${JSON.stringify(s.falseAlarms.byKind)}, snr median ${s.falseAlarms.snrMedian} dB`,
  );
  console.log(`  breath-match kinds: ${JSON.stringify(s.breath.matchedKinds)}`);
  console.log(`  forced ends   : ${JSON.stringify(s.forcedEnds)}`);
}

// Breath miss vs breath peak, clean level — the physical limit statement.
const clean = results[0];
console.log('\nbreath misses at clean, by peak dBFS:');
console.log('  missed  :', clean.breath.missedPeaks.sort((a, b) => a - b).join(' ') || '(none)');
console.log('  detected:', clean.breath.detectedPeaks.sort((a, b) => a - b).join(' ') || '(none)');

// ── Label quality tally (feeds the report's reliability statement) ───────────
const allB = labels.files.flatMap((f) => f.breaths);
const allS = labels.files.flatMap((f) => f.speech);
const hr = (e) => (e.floorBeforeDbfs == null ? null : e.peakDbfs - e.floorBeforeDbfs);
const labelQuality = {
  breathLabels: allB.length,
  breathHeadroomBuckets: {
    '>=10dB': allB.filter((b) => hr(b) >= 10).length,
    '6-10': allB.filter((b) => hr(b) >= 6 && hr(b) < 10).length,
    '3-6': allB.filter((b) => hr(b) >= 3 && hr(b) < 6).length,
    '0-3': allB.filter((b) => hr(b) >= 0 && hr(b) < 3).length,
    '<0 (dip in a loud region)': allB.filter((b) => hr(b) < 0).length,
  },
  breathsScoredPerLevel: results[0].breath.scored,
  speechSegments: allS.length,
  speechScoredPerLevel: results[0].speech.scored,
};

// ── Breath-detection collapse curve, pooled across levels ────────────────────
// Each (breath, level) trial has breath peak and the measured floor of that mix;
// bin by SNR = peak − floor to find where detection probability crosses 50%.
// MERGED trials are excluded: a breath inside an already-open turn carries no
// information about the SNR gate — the detector never got to make the decision.
const snrTrials = [];
for (const R of results) {
  const F = pct(R.floors.filter((v) => v != null), 50);
  if (F == null) continue;
  for (const t of R.breath.trials) {
    if (t.outcome === 'merged') continue;
    snrTrials.push({ snr: t.peakDbfs - F, detected: t.outcome === 'detected' });
  }
}
snrTrials.sort((a, b) => a.snr - b.snr);
const bins = [];
for (let lo = 0; lo <= 30; lo += 5) {
  const inBin = snrTrials.filter((t) => t.snr >= lo && t.snr < lo + 5);
  if (inBin.length) bins.push({ snrRange: `${lo}..${lo + 5}`, n: inBin.length, detRate: +(inBin.filter((t) => t.detected).length / inBin.length).toFixed(3) });
}
console.log('\nbreath detection vs breath-to-floor SNR (merged trials excluded, pooled across levels):');
for (const b of bins) console.log(`  SNR ${b.snrRange} dB : ${(100 * b.detRate).toFixed(0)}%  (n=${b.n})`);
// 50% crossing by linear interpolation between adjacent bins.
let collapseSnr = null;
for (let i = 1; i < bins.length; i++) {
  if (bins[i - 1].detRate < 0.5 && bins[i].detRate >= 0.5) {
    const f = (0.5 - bins[i - 1].detRate) / (bins[i].detRate - bins[i - 1].detRate);
    collapseSnr = +(i - 1 + f).valueOf() * 5 + 2.5;
    collapseSnr = +collapseSnr.toFixed(1);
    break;
  }
}
const breathPeaks = allB.map((b) => b.peakDbfs).sort((a, b2) => a - b2);
const medianBreathPeak = breathPeaks[Math.floor(breathPeaks.length / 2)];
console.log(`  → 50% detection at breath SNR ≈ ${collapseSnr} dB`);
console.log(`  → median labelled breath peaks at ${medianBreathPeak} dBFS, so detection collapses at a floor of ≈ ${(medianBreathPeak - (collapseSnr ?? 0)).toFixed(1)} dBFS`);
console.log('\nlabel quality:', JSON.stringify(labelQuality));

writeFileSync(
  process.env.SWEEP_OUT ?? join(MEDIA, 'corpus-score-results.json'),
  JSON.stringify(
    {
      generated: new Date().toISOString(),
      detector: 'tape-app/public/core/onset.js (imported unmodified, run in node)',
      files: labels.files.length,
      levels: LEVELS,
      scoringRules: {
        CAL_GUARD_MS, SPEECH_DET_WIN, BREATH_DET_WIN, SPEECH_TIMING_WIN, HEADROOM_MIN_DB,
        quietBeforeSpeechMs: labels.criteria.QUIET_BEFORE_MS,
        quietBeforeBreathMs: labels.criteria.BREATH_QUIET_BEFORE_MS,
      },
      summary,
      labelQuality,
      breathCollapse: { bins, collapseSnr50: collapseSnr, medianBreathPeakDbfs: medianBreathPeak },
    },
    null,
    1,
  ),
);
console.log('\nwrote ' + (process.env.SWEEP_OUT ?? 'media/corpus-score-results.json'));
